        window.openShiptechPdfViewer = function (rawUrl, title, badge, ev) {
            if (ev && typeof ev.preventDefault === 'function') {
                ev.preventDefault();
            }
            var cleanUrl = String(rawUrl || '').trim();
            if (!cleanUrl) return false;
            var encodedUrl = encodeURI(decodeURI(cleanUrl));
            var docTitle = title || 'Official Document';
            var docBadge = badge || 'OFFICIAL PDF';

            var modal = document.getElementById('shiptech-pdf-modal');
            if (modal) {
                var modalFrame = document.getElementById('modal-pdf-frame');
                var modalTitle = document.getElementById('modal-pdf-title');
                var modalBadge = document.getElementById('modal-pdf-badge');
                var modalDl = document.getElementById('modal-pdf-download');
                var modalNewTab = document.getElementById('modal-pdf-newtab');
                if (modalFrame) modalFrame.src = encodedUrl + '#toolbar=1&navpanes=0&view=FitH';
                if (modalTitle) modalTitle.textContent = docTitle;
                if (modalBadge) modalBadge.textContent = docBadge;
                if (modalDl) modalDl.href = encodedUrl;
                if (modalNewTab) modalNewTab.href = encodedUrl;
                modal.style.display = 'flex';
                document.body.style.overflow = 'hidden';
            }
            return false;
        };
        window.closeShiptechPdfViewer = function () {
            var modal = document.getElementById('shiptech-pdf-modal');
            if (modal) {
                modal.style.display = 'none';
                var modalFrame = document.getElementById('modal-pdf-frame');
                if (modalFrame) modalFrame.src = 'about:blank';
                document.body.style.overflow = '';
            }
        };
